<article class="pl-card rv-highlight"><h4><i class="bi bi-star" aria-hidden="true"></i> Overall rating</h4><div class="rv-number"><?= $reviews['average'] === null ? '&mdash;' : number_format($reviews['average'], 1) ?><small>/ 5</small></div><p><?= $reviews['count'] ? 'Average across all published demo reviews.' : 'No ratings yet.' ?></p></article>
